import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;
import java.util.Arrays;
import java.util.Locale;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String line = reader.readLine();
        while (line != null && line.trim().isEmpty()) {
            line = reader.readLine();
        }
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        int n = Integer.parseInt(st.nextToken());
        double d = Double.parseDouble(st.nextToken());

        double[] pos = new double[n + 1];
        double[] cap = new double[n];

        for (int i = 0; i < n; i++) {
            line = reader.readLine();
            while (line != null && line.trim().isEmpty()) {
                line = reader.readLine();
            }
            st = new StringTokenizer(line);
            pos[i] = Double.parseDouble(st.nextToken());
            cap[i] = Double.parseDouble(st.nextToken());
        }
        pos[n] = d;

        double[] dp = new double[n + 1];
        Arrays.fill(dp, Double.POSITIVE_INFINITY);
        dp[0] = 0.0;

        for (int i = 0; i < n; i++) {
            if (dp[i] == Double.POSITIVE_INFINITY) continue;
            for (int j = i + 1; j <= n; j++) {
                double dist = pos[j] - pos[i];
                double time = (dist * dist) / cap[i];
                if (dp[i] + time < dp[j]) {
                    dp[j] = dp[i] + time;
                }
            }
        }

        System.out.printf(Locale.US, "%.3f\n", dp[n]);
    }
}
